import ast, sys
tree = ast.parse(open('/workspace/submission/main.py').read())
# report defined names and simple unused-variable scan
names = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
        names.add(node.id)
    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
        names.add(node.name)
used = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
        used.add(node.id)
    if isinstance(node, ast.Attribute):
        pass
print('assigned but never loaded:', sorted(n for n in names - used if not n.startswith('_')))
PYEOF
